  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % NOISE_PARAMS.reductionInterval === 0) {
      this.pendingReduction = NOISE_PARAMS.reductionAmount;
    }
    if (score % 100 === 0) {
      this._fireAuraBlade(api);
    }
  }

  private _fireAuraBlade(api: GameSceneAPI): void {
    const scene = api.scene;
    const px = api.player.x;
    const py = api.player.y - 20;

    // 오러 블레이드: 플레이어 위치에서 위쪽으로 날아가는 슬래시 트레일
    const blade = scene.add.graphics();
    blade.setDepth(200);

    // 이동용 컨테이너 역할 — y 좌표를 tween으로 올림
    let bladeY = py;
    const startAngle = -160;
    const endAngle  = -20;

    const moveTween = scene.tweens.addCounter({
      from: 0,
      to: 1,
      duration: 500,
      ease: 'Quad.easeOut',
      onUpdate: (tween) => {
        const progress = tween.getValue();
        bladeY = py - progress * 650; // 위로 650px 이동
        blade.clear();

        const alpha = 1 - progress;
        const currentAngle = Phaser.Math.Linear(startAngle, endAngle, Math.min(progress * 2, 1));

        blade.lineStyle(18, 0x88ffff, alpha * 0.9);
        blade.strokeCircle(px, bladeY, 0); // stroke 준비
        blade.beginPath();
        blade.arc(px, bladeY, 55, Phaser.Math.DegToRad(startAngle), Phaser.Math.DegToRad(currentAngle), false);
        blade.strokePath();

        blade.lineStyle(8, 0xffffff, alpha * 0.7);
        blade.beginPath();
        blade.arc(px, bladeY, 52, Phaser.Math.DegToRad(startAngle), Phaser.Math.DegToRad(currentAngle), false);
        blade.strokePath();
      },
      onComplete: () => {
        blade.destroy();
      },
    });

    // 혹시 씬이 일찍 파괴되면 정리
    scene.events.once('shutdown', () => {
      moveTween.stop();
      blade.destroy();
    });
  }
}

